package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamMudraClassicalBank2 {
    private const val T = "හස්ත මුද්‍රා විද්‍යාව හා භාරතීය/විදේශීය සම්භාව්‍ය නර්තන"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පද්මකෝෂ හස්තයේ ඇඟිලිවල අග්‍ර පමණක් තරමක් ලිහිල්ව හකුළුවා ගත් අසංයුත හස්තය හඳුන්වන්නේ කුමන නමකින්ද?", "චතුර හස්තය", "සිංහමුඛ හස්තය", "කටකාමුඛ හස්තය", "කංගුල හස්තය", "චතුර හස්තය මද ප්‍රමාණය, රන්, සතුට හා සුළු දෙයක් නිරූපණයට යොදයි."),
        q("කපිත්ථ හස්තයේදී සුළැඟිල්ල සහ වෙදැඟිල්ල පිටතට දිගු කර තබන හස්ත මුද්‍රාව කුමක්ද?", "කටකාමුඛ හස්තය", "භ්‍රමර හස්තය", "හංසපක්ෂ හස්තය", "ත්‍රිශූල හස්තය", "කටකාමුඛ හස්තය මල් නෙළීම, මුතු මාලයක් ඇල්ලීම හා පූජා දැක්වීම සඳහා යොදයි."),
        q("මැදැඟිල්ල හා මහපටැඟිල්ලේ අග්‍ර එක්කර වෙදැඟිල්ල නවා අනෙක් ඇඟිලි විහිදුවන මුද්‍රාව කුමක්ද?", "කංගුල හස්තය", "අලපද්ම හස්තය", "මුකුල හස්තය", "තාම්‍රචූඩ හස්තය", "කංගුල හස්තය සීනු හඬ, ගෙඩි වර්ග, පොල් හා කුඩා දරුවා දැක්වීමට යෙදේ."),
        q("සර්පශීර්ෂ හස්තයේ සුළැඟිල්ල පමණක් කොක්කක් සේ නවා තබන මුද්‍රාව කුමක්ද?", "හංසපක්ෂ හස්තය", "ශුකතුණ්ඩ හස්තය", "පතක හස්තය", "සූචි හස්තය", "හංසපක්ෂ හස්තය ඉලක්කම් හය, ඉණිමග, සිතුවම් ඇඳීම හා සෙවණ දැක්වීමට යොදයි."),
        q("දබරැඟිල්ල, මැදැඟිල්ල සහ වෙදැඟිල්ල ඉහළට දිගු කර මහපටැඟිල්ල හා සුළැඟිල්ල එක්කරන මුද්‍රාව කුමක්ද?", "ත්‍රිශූල හස්තය", "ශිඛර හස්තය", "චන්ද්‍රකලා හස්තය", "මෘගශීර්ෂ හස්තය", "ත්‍රිශූල හස්තය බෙලි කොළ තුන, ත්‍රිත්වය හා ශිව ආයුධය දැක්වීමට යොදාගනී."),
        q("කටකාමුඛ හස්ත දෙක මැණික් කටුව ළඟින් හරස් කොට තබන සංයුත හස්තය කුමක්ද?", "කටකාවර්ධන හස්තය", "අංජලී හස්තය", "ගරුඩ හස්තය", "මත්ස්‍ය හස්තය", "කටකාවර්ධන හස්තය රාජාභිෂේකය, වන්දනාව හා මංගල උත්සව දැක්වීමට යොදයි."),
        q("පතක හස්ත දෙක එකට තබා මැදැඟිලි දෙක නවා අත් දෙක ඉදිරියට පෙන්වන මුද්‍රාව කුමක්ද?", "ශකට හස්තය", "පුෂ්පපුට හස්තය", "ඩෝලා හස්තය", "කපෝත හස්තය", "ශකට හස්තය රාක්ෂයන් හා කරත්ත රෝදය නිරූපණය කිරීම සඳහා යොදයි."),
        q("වම් අතේ මහපටැඟිල්ල මත දකුණු අතේ ඇඟිලි හතර පටලවා මහපටැඟිලි දිගු කරන මුද්‍රාව කුමක්ද?", "ශංඛ හස්තය", "චක්‍ර හස්තය", "කූර්ම හස්තය", "වරාහ හස්තය", "ශංඛ හස්තයෙන් විෂ්ණු දෙවියන්ගේ හක්ගෙඩිය නිරූපණය කෙරේ."),
        q("ශිඛර හස්ත දෙක වැළමිටි වෙත දිගු කර උරහිස් මට්ටමින් හිස දෙපසට යොමු කරන මුද්‍රාව කුමක්ද?", "බේරුණ්ඩ හස්තය", "නිෂධ හස්තය", "අවහිත්ථ හස්තය", "උත්සංග හස්තය", "බේරුණ්ඩ හස්තය හිස් දෙකක් ඇති බේරුණ්ඩ පක්ෂියා නිරූපණය කරයි."),
        q("අලපද්ම හස්ත දෙක පපුව ඉදිරිපිට හරස් කොට ස්ත්‍රී ස්වරූපය හෝ සියුමැලි බව දක්වන මුද්‍රාව කුමක්ද?", "අවහිත්ථ හස්තය", "ස්වස්තික හස්තය", "කර්කට හස්තය", "නාගබන්ධ හස්තය", "අවහිත්ථ හස්තය ක්‍රීඩා පන්දුව, කාන්තා ලාලිත්‍යය හා රහස් සැඟවීම දැක්වීමට යොදයි."),
        q("දකුණු මුෂ්ටි හස්තය වම් කපිත්ථ හස්තයේ සිදුර තුළින් යොමු කර තබන මුද්‍රාව කුමක්ද?", "නිෂධ හස්තය", "ශිවලිංග හස්තය", "පාශ හස්තය", "කීලක හස්තය", "නිෂධ හස්තය ඉවසීම, ස්ථිර අධිෂ්ඨානය හා ධෛර්යය දැක්වීමට යොදයි."),
        q("නාගබන්ධ හස්තය හා ස්වස්තික හස්තය අතර ප්‍රධාන වෙනස කුමක්ද?", "නාගබන්ධයේදී සර්පශීර්ෂ හස්තද ස්වස්තිකයේදී පතක හස්තද හරස් කරයි", "දෙකම තනි අතින් පමණක් දක්වයි", "දෙකේම මුෂ්ටි හස්ත භාවිත වේ", "ස්වස්තිකයේ ඇඟිලි සියල්ල නවයි", "සංයුත හස්තවල මූලික අසංයුත හස්ත අනුව අර්ථ හා හැඩතල වෙනස් වේ."),
        q("හස්ත මුද්‍රාවක් පැහැදිලිව ප්‍රේක්ෂකයාට සන්නිවේදනය වීම සඳහා අත්‍යවශ්‍යයෙන්ම එක්විය යුතු අනෙක් අංගය කුමක්ද?", "දෘෂ්ටි හෙවත් ඇස් යොමු කිරීම සහ මුහුණේ භාවය", "වේගවත් පිනුම් ගැසීම", "උස් හඬින් කෑගැසීම", "බෙරය නතර කිරීම", "යත්‍ර හස්තස් තතෝ දෘෂ්ටි යන ශ්ලෝකය අනුව අත යන දෙසට ඇස හා සිත යොමු විය යුතුය."),
        q("නන්දිකේශ්වරගේ 'අභිනය දර්පණය' අනුව 'යත්‍ර හස්තස් තතෝ දෘෂ්ටි' යන්නෙහි ඉතිරි පියවර පිළිවෙළ කුමක්ද?", "ඇස යොමු වන තැන සිතත්, සිත ඇති තැන භාවයත්, භාවය ඇති තැන රසයත් උපදී", "ඇස යොමු වන තැන බෙරයත් තාලයත් උපදී", "අත යොමු වන තැන ගීතය පමණක් උපදී", "දෙපා තබන තැන වේදිකාව උපදී", "හස්තය, දෘෂ්ටිය, මනස, භාවය හා රසය එකට බැඳී පවතින බව අභිනය දර්පණය උගන්වයි."),
        q("උඩරට නර්තනයේදී මල් වට්ටියක් හෝ පහනක් රැගෙන යන බව දැක්වීමට වඩාත් උචිත මුද්‍රාව කුමක්ද?", "පුෂ්පපුට හෝ පද්මකෝෂ හස්තය", "සූචි හස්තය", "කර්කට හස්තය", "ශකට හස්තය", "පුෂ්පපුට මුද්‍රාව දෑතින් මල් පූජාව පිළිගැන්වීම මනාව නිරූපණය කරයි."),
        q("නර්තනයේදී 'වැස්ස' හෝ 'ගංගා ගලා යාම' අභිනය කිරීමේදී යොදාගත හැකි වඩාත් උචිත හස්ත මුද්‍රා මොනවාද?", "පතක හා ත්‍රිපතක හස්ත", "මුෂ්ටි හස්තය", "තාම්‍රචූඩ හස්තය", "නිෂධ හස්තය", "පතක හස්තය ඉහළ සිට පහළට සෙමින් චලනය කිරීමෙන් වැස්ස හා දිය ඇලි දැක්විය හැක."),
        q("හිරු සහ සඳු දැක්වීම සඳහා අසංයුත හස්ත මුද්‍රා අතරින් වඩාත් බහුලව යොදාගන්නේ කුමක්ද?", "සූචි හෝ අලපද්ම හස්තය සහ අර්ධචන්ද්‍ර හස්තය", "මුෂ්ටි හා කූර්ම හස්ත", "සිංහමුඛ හා කර්කට හස්ත", "ශකට හා ඩෝලා හස්ත", "අර්ධචන්ද්‍ර හා චන්ද්‍රකලා මුද්‍රා සඳු සඳහාද අලපද්ම හා සූචි හිරු සඳහාද යොදයි."),
        q("සම්ප්‍රදායිකව 'පූජාව' හෝ 'නමස්කාරය' ප්‍රකාශ කිරීමේදී දෙවියන් වෙනුවෙන් අංජලී හස්තය තබනු ලබන්නේ කොතැනද?", "හිසට ඉහළින්", "පපුව ඉදිරිපිට", "මුහුණ ඉදිරිපිට", "උකුළ අසල", "දෙවියන්ට හිසට ඉහළින්ද ගුරුවරුන්ට මුහුණ ඉදිරියෙන්ද ප්‍රේක්ෂකයන්ට පපුව ඉදිරියෙන්ද අංජලී තබයි."),
        q("ගුරුවරුන්ට නමස්කාර කිරීමේදී අංජලී හස්තය තබනු ලබන නිවැරදි ස්ථානය කුමක්ද?", "නළල හෙවත් මුහුණ ඉදිරිපිට", "දණහිස් ඉදිරිපිට", "උරහිසට පිටුපසින්", "පාද අසල", "සම්භාව්‍ය නර්තන නීතිය අනුව ගුරුවරුන්ට ආචාර කිරීමට මුහුණ මට්ටමේ අංජලී හස්තය තබයි."),
        q("ප්‍රේක්ෂකයන්ට සහ සභාවට ආචාර කිරීමේදී අංජලී හස්තය තබනු ලබන්නේ කුමන ස්ථානයේද?", "පපුව ඉදිරිපිට", "හිස මුදුනේ", "කලවා දෙපස", "බෙල්ලට පිටුපසින්", "සභාවට සහ මිතුරන්ට ආචාර කිරීම සඳහා පපුව ඉදිරිපිට අංජලී මුද්‍රාව දක්වනු ලැබේ."),
        q("දේශීය නර්තනයේදී හස්ත මුද්‍රා පමණක් නොව අත්වල අලංකාරය ගෙනෙන 'ගජගා ගමන' සඳහා වැදගත් වන අංග චලනය කුමක්ද?", "මැණික් කටුව සහ වැළමිට නම්‍යශීලීව හැසිරවීම", "දෑත් තදින් කඳට ඇලවා තැබීම", "ඇඟිලි තදින් මිට මෙළවීම", "උරහිස් ඉහළට ඔසවා ගැනීම", "දේශීය නර්තනයේ උරහිස්, වැළමිට හා මැණික් කටුව සුමටව කැරකැවීම අලංකාරය වැඩි කරයි."),
        q("භරත නාට්‍යම් රංගනයේදී වර්ණම් අංගයට පසුව ඉදිරිපත් කරන අභිනයට මුල්තැන දෙන ප්‍රේමාත්මක අංගය කුමක්ද?", "පදම් හෝ ජාවලි", "අලාරිප්පු", "ජතිස්වරම්", "මල්ලාරි", "පදම් සහ ජාවලි මන්දගාමී ලයකින් ශෘංගාර හා භක්ති රසයන් ඉස්මතු කරන අභිනය අංග වේ."),
        q("භරත නාට්‍යම් හිදී 'ජතිස්වරම්' අංගය මඟින් ඉදිරිපත් කෙරෙන්නේ කුමක්ද?", "ස්වර හා තාල රටා මත පදනම් වූ ශුද්ධ නෘත්ත නර්තනයකි", "කතා පුවතක් නිරූපණය කරන දෙබස් කොටසකි", "පූජා ගායනයක් පමණි", "වෙස්මුහුණු නැටුමකි", "ජතිස්වරම් හි සාහිත්‍ය වචන නොමැති අතර ස්වර හා ජතිවලට නෘත්ත අඩවු ඉදිරිපත් කෙරේ."),
        q("භරත නාට්‍යම් නැටුමක ප්‍රේක්ෂකයාට කතාවක් හෝ භක්ති ගීතයක් මුලින්ම අභිනය කර පෙන්වන අංගය කුමක්ද?", "ශබ්දම්", "තිල්ලානා", "අලාරිප්පු", "තත්කාර්", "ශබ්දම් යනු අලාරිප්පු හා ජතිස්වරම්වලට පසුව එන පළමු අභිනය ප්‍රමුඛ අංගයයි."),
        q("භරත නාට්‍යම් සම්ප්‍රදායේ නර්තන ශිල්පිනිය හිස මත පළඳින හිරු හා සඳු සංකේතවත් කරන ආභරණ යුගලය කුමක්ද?", "සූර්ය පිරෙයි සහ චන්ද්‍ර පිරෙයි", "ජටා පටිය සහ සිළම්බු", "තෝඩු සහ කූරු", "වංගි සහ අඩ්ඩිගෙයි", "භරත නාට්‍යම් හිස පැළඳුම් අතර හිස දෙපස පළඳින සූර්ය චන්ද්‍ර ආභරණ ප්‍රධාන වේ."),
        q("භරත නාට්‍යම් හිස් මුදුන පළඳින 'රාක්කොඩි' ආභරණය මෙන්ම නළල මැද පළඳින ආභරණය කුමක්ද?", "නෙත්ති චුට්ටි", "හවඩිය", "සිළම්බු", "මුක්කුත්ති", "නෙත්ති චුට්ටි යනු නළල මැද එල්ලෙන අලංකාර භරත නාට්‍යම් ආභරණයකි."),
        q("භරත නාට්‍යම් හා උඩරට නර්තනය යන දෙකෙහිම නැට්ටුවාගේ පාදයේ තාල හඬ නැංවීමට පළඳින ආභරණය කුමක්ද?", "ගෙජ්ජි හෙවත් ගුංගුරු", "පා සළඹ හෙවත් සිළම්බු පමණක්", "කයිවලල්ල", "නූපුර මාලය", "දකුණු ඉන්දියාවේ සලංගෙයි ලෙසත් ලංකාවේ ගෙජ්ජි ලෙසත් හඳුන්වන මිණි ගෙඩි දෙපයේ බඳී."),
        q("භරත නාට්‍යම් සම්ප්‍රදාය විධිමත් වේදිකා අංග මාලාවකට සකස් කළ 19 වන සියවසේ සොහොයුරන් හතරදෙනා කවුද?", "තන්ජෝර් චතුෂ්කය", "නාට්‍ය මුනිවරුන්", "රාජ සභා පඬිවරුන්", "මලය රජ සොහොයුරන්", "චින්නයියා, පොන්නයියා, ශිවානන්දම් සහ වඩිවේලු යන තන්ජෝර් සොහොයුරෝ මේ ප්‍රසංග මාලාව සැකසූහ."),
        q("තන්ජෝර් චතුෂ්කය විසින් සකසන ලද සම්මත භරත නාට්‍යම් ප්‍රසංග පෙළගැස්ම හඳුන්වන්නේ කුමන නමකින්ද?", "මාර්ගම්", "තාණ්ඩව", "කච්චේරි", "වන්නම් පෙළ", "අලාරිප්පුවේ සිට තිල්ලානාව දක්වා වූ පෙළගැස්ම මාර්ගම් ලෙස හැඳින්වේ."),
        q("කථක් නර්තනයේදී වාද්‍ය ශිල්පියා හා නැට්ටුවා අතර සිදුවන රිද්මයානුකූල අභියෝගාත්මක තරගකාරී අංගය කුමක්ද?", "ජුගල්බන්දි හෙවත් සවාල් ජවාබ්", "වර්ණම්", "අලාරිප්පු", "තිරනොට්ටු", "සවාල් ජවාබ් හිදී තබ්ලා වාදකයා වයන තාල බෝල්වලට නැට්ටුවා පාදයෙන් පිළිතුරු දෙයි."),
        q("කථක් නර්තන ප්‍රසංගයක් ආරම්භයේදී සිදු කරන දෙවියන්ට හෝ ගුරුවරුන්ට ආචාර කිරීමේ අංගය කුමක්ද?", "වන්දනා හා ආමද්", "තිල්ලානා", "පදම්", "තරංගම්", "ආමද් යනු පිවිසීම යන අරුතැතිව වේදිකාවට පිවිසෙන ආරම්භක කථක් අංගයයි."),
        q("කථක් නැටුමේදී එක් තැනක සිට තාලයට අනුව දක්වන කෙටි අභිනය අංගය හඳුන්වන්නේ කෙසේද?", "ගත් භාව් හෝ කවිත්ත", "අරමණ්ඩි", "ත්‍රිභංග", "මණ්ඩි", "ගත් භාව් හිදී වචන නැතිව බටනළා නාදයට රාධා ක්‍රිෂ්ණා කතා මුහුණින් හා දෑතින් රඟ දැක්වේ."),
        q("කථක් නර්තනයේදී කියන සාම්ප්‍රදායික තාල ශබ්ද අක්ෂර හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "බෝල් සහ පරන්", "සුරල් පද", "තානම්", "සොල්කට්ටු", "කථක් හිදී තා තෙයි තෙයි තත් වැනි බෝල් හා පඛවාජ් පරන් මුඛයෙන් කියා පාදයෙන් නටයි."),
        q("කථක් නැටුමේදී තුන් වරක් නොකඩවා ගසා 'සම' මත අවසන් කරන සුන්දර තාල කැබැල්ල කුමක්ද?", "තිහායි", "ජති", "කලශම්", "අඩව්", "තිහායි යනු සංගීතයේ හා කථක් නර්තනයේ සෑම අංගයක්ම තුන්වරක් වයා අවසන් කරන ක්‍රමයයි."),
        q("කථක් නර්තනයේදී කකුලේ බඳින ගෙජ්ජි පොට හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "ගුංගුරු", "සිළම්බු", "සලංගෙයි", "කිකිණි", "එක් පාදයක ගෙජ්ජි 100 සිට 200 දක්වා ඇමිණූ ගුංගුරු වැල් කථක් ශිල්පීන් පළඳී."),
        q("ලෝක ප්‍රකට කථක් නර්තන ගුරුවරයෙකු වන පණ්ඩිත් බිර්ජු මහාරාජ් අයත් වන්නේ කුමන ඝරානාවටද?", "ලක්නව් ඝරානාව", "ජයිපූර් ඝරානාව", "රයිගර් ඝරානාව", "තන්ජෝර් ඝරානාව", "පණ්ඩිත් බිර්ජු මහාරාජ් ලක්නව් ඝරානාවේ අග්‍රගණ්‍ය කථක් ශිල්පියෙකි."),
        q("කථකලි නැටුමේදී කතා වස්තු වශයෙන් ප්‍රධාන ලෙස ගනු ලබන මහා කාව්‍ය ග්‍රන්ථ මොනවාද?", "මහාභාරතය, රාමායණය සහ භාගවත පුරාණය", "මහාවංශය සහ දීපවංශය", "උම්මග්ග ජාතකය සහ වෙස්සන්තර ජාතකය", "ශකුන්තලා සහ මේඝදූතය", "දේව හා වීර පුරාවෘත්ත රැගත් ඉන්දීය මහා කාව්‍ය කථකලි අට්ටකථා සඳහා පාදක විය."),
        q("කථකලි වේෂ නිරූපණයේදී සාමකාමී කාන්තා චරිත, සෘෂිවරුන් හා බ්‍රාහ්මණ චරිත සඳහා යොදන මුහුණු වර්ණය කුමක්ද?", "මිනුක්කු හෙවත් ලා කහ සහ රෝස පැහැය", "තද කළු පැහැති කරි වේෂය", "තද කොළ පැහැති පච්ච වේෂය", "නිල් පැහැති වේෂය", "මිනුක්කු යනු මුහුණ ස්වාභාවික ලෙස ඔප දැමීමෙන් කරන සෞම්‍ය වේෂ නිරූපණයයි."),
        q("කථකලි නැට්ටුවෙකුගේ මුහුණ දෙපස කඩදාසි හා සහල් පිටි තලපයෙන් සකසන සුදු රාමුව හඳුන්වන්නේ කුමන නමකින්ද?", "චුට්ටි", "තිරනොට්ටු", "පච්ච", "කුමිල්", "චුට්ටි රාමුව මුහුණේ හැඟීම් ප්‍රේක්ෂකයාට ඉතා පැහැදිලිව ඉස්මතු කර පෙන්වීමට උදව් වේ."),
        q("කථකලි නර්තනයේදී වචනයක් හෝ නොකියා නැට්ටුවා අදහස් පළ කරන්නේ කෙසේද?", "හස්ත මුද්‍රා සහ නවරස මුහුණු අභිනයෙන්", "වේදිකාවේ පුවරු එසවීමෙන්", "තිරය ඇරීමෙන් හා වැසීමෙන්", "වාද්‍ය භාණ්ඩ වාදනය කිරීමෙන්", "කථකලි ශිල්පියා පසුබිම් ගායකයා ගයන පදවලට මුද්‍රා 24 සහ නවරසයෙන් පිළිතුරු දෙයි."),
        q("කථකලි හස්ත මුද්‍රා පදනම් වී ඇති කේරළයේ සුවිශේෂී ග්‍රන්ථය කුමක්ද?", "හස්ත ලක්ෂණ දීපිකා", "මහාවංශ ටීකාව", "තාල පත්‍ර සංග්‍රහය", "සිංහල නැටුම් පොත", "හස්ත ලක්ෂණ දීපිකා ග්‍රන්ථයේ දැක්වෙන මූලික මුද්‍රා 24 කථකලි හි භාවිත වේ."),
        q("කථකලි නැටුමේ පසුබිම් ගායකයා ගයන මලයාලම් හා සංස්කෘත මිශ්‍ර කාව්‍ය සංගීතය හඳුන්වන්නේ කුමන නමකින්ද?", "සෝපාන සංගීතය", "හින්දුස්ථානි ඛයාල්", "කපිරිඤ්ඤා ගී", "රබන් පද", "සෝපාන සංගීතයට අනුව ප්‍රධාන ගායකයා චෙන්ගිලා හෙවත් ඝණ්ටාර තැටිය වයමින් ගයයි."),
        q("කථකලි ශිල්පීන් රංගනය සඳහා භාවිත කරන අලංකාර විශාල හිස් පැළඳුම හඳුන්වන්නේ කුමන නමකින්ද?", "කිරීටම්", "වෙස් තට්ටුව", "කුමිල්", "පතකය", "කිරීටම් නමැති ලී හා පිත්තලවලින් කළ විශාල ඔටුන්න කථකලි චරිතයට දේව තේජසක් ලබා දෙයි."),
        q("මණිපුරි නර්තනයේදී හිස හා ගෙල චලනය කිරීමේදී ඒකාකාරී මෘදු චලනයක් පවත්වා ගන්නේ ඇයි?", "මණිපුරි ලස්ය සම්ප්‍රදායේ ආචාරශීලී හා සන්සුන් බව රැකීමට", "හිස් වැස්ම බර වැඩි නිසා", "බෙර වාදකයා නොපෙනෙන නිසා", "ගෙජ්ජි හඬ වැඩි කිරීමට", "මණිපුරි නැට්ටුවෝ අනෙක් සම්ප්‍රදායන් මෙන් දෑස් තියුණු ලෙස කැරකවීම හෝ තදින් පාද ගැසීම නොකරති."),
        q("මණිපුරි නැටුමේදී පාද පොළොවට තදින් නොගසා මෘදු ලෙස තබන්නේ කෙසේද?", "පාදයේ ඉදිරිපස කොටස මෘදුව හා වසන්තමය ලෙස තබමින්", "සපත්තු පැළඳ ගනිමින්", "දණහිස් මතින් ඇවිදිමින්", "දෙපා ඔසවා උඩ පනිමින්", "මණිපුරි ශිල්පීන්ගේ පාද චලනය ජල තරංග මෙන් සුමට හා නිහඬ වේ."),
        q("මණිපුරි නැටුමේදී ගෙජ්ජි නොබැඳ සුදු පැහැති සිහින් මුස්ලින් වේල් එකකින් මුහුණ මඳක් ආවරණය කරන්නේ ඇයි?", "ලැජ්ජාශීලී හා පූජනීය භක්ති ස්වභාවය ඉස්මතු කිරීමට", "උණුසුමෙන් බේරීමට", "හඳුනා ගැනීම වැළැක්වීමට", "හුස්ම ගැනීම පහසු කිරීමට", "රාස් ලීලා හි ගෝපිකාවන්ගේ පවිත්‍ර භක්තිය හා විනීත බව එයින් නිරූපණය වේ."),
        q("ඔඩිසි නර්තනයේ පිරිමි චරිත හා ජවසම්පන්න සමචතුරශ්‍ර ඉරියව්ව හඳුන්වන්නේ කුමන නමකින්ද?", "චෞක් ඉරියව්ව", "ත්‍රිභංග ඉරියව්ව", "අරමණ්ඩි ඉරියව්ව", "සමපාද ඉරියව්ව", "ජගන්නාථ දෙවියන්ගේ ස්වරූපය සිහිගන්වන සමචතුරශ්‍ර ඉරියව්ව චෞක් නම් වේ."),
        q("ඔඩිසි නර්තනයේ ප්‍රධාන ස්වභාවික තාල බෙරය කුමක්ද?", "මර්දලා", "චෙන්ඩා", "තම්මැට්ටම", "උඩැක්කිය", "මර්දලා නම් මැටි හෝ දැව බෙරය ඔඩිසි සංගීතයේ ප්‍රධාන රිද්මය සපයයි."),
        q("ඔඩිසි නර්තනයේ ආරම්භක පූජා නර්තන අංගය කුමක්ද?", "මංගලාචරණ", "අලාරිප්පු", "තිරනොට්ටු", "වන්දනා", "මංගලාචරණ හිදී නැට්ටුවා මල් අතැතිව භූමි වන්දනාව හා ගණේෂ හෝ ජගන්නාථ වන්දනාව ඉදිරිපත් කරයි."),
        q("ඔඩිසි නර්තනයේදී ශිව දෙවියන් හා පාර්වතී දේවිය නිරූපණය කරන රිද්මයානුකූල ශුද්ධ නර්තන අංගය කුමක්ද?", "බට්ටු නෘත්‍ය", "මෝක්ෂ", "පල්ලවි", "අෂ්ටපදි", "බට්ටු නෘත්‍යයේදී ශිල්පියා විවිධ වාද්‍ය භාණ්ඩ වාදනය කරන මූර්ති ඉරියව් නිරූපණය කරයි."),
        q("ඔඩිසි නර්තන ප්‍රසංගයක අවසානයේදී ආත්ම විමුක්තිය සංකේතවත් කරමින් ඉදිරිපත් කරන වේගවත් අංගය කුමක්ද?", "මෝක්ෂ", "තිල්ලානා", "පදම්", "තරංගම්", "මෝක්ෂ අංගය ඉතා වේගවත් උත්සවශ්‍රීයෙන් යුතු නෘත්ත හා ස්තෝත්‍ර ගායනයකින් අවසන් වේ."),
        q("කුචිපුඩි නැටුමේදී පිත්තල තැටියේ ගැටිය මත සිට හිස මත දිය කළයක් තබාගෙන නටන අංගය කුමක්ද?", "තරංගම්", "අලාරිප්පු", "මෝක්ෂ", "ජතිස්වරම්", "තරංගම් හිදී නැට්ටුවාගේ ඉහළම සමතුලිතතාව හා පාද පාලනය ප්‍රදර්ශනය වේ."),
        q("ඉන්දීය ශාස්ත්‍රීය නර්තන සම්ප්‍රදායන් හා සසඳන විට උඩරට නර්තනයේ අනන්‍ය ලක්ෂණයක් වන්නේ කුමක්ද?", "ශ්‍රී ලාංකේය පංචතූර්ය වාද්‍ය භාණ්ඩ හා සිංහල වන්නම් ගායනය", "කර්ණාටක සංගීතය පමණක් භාවිතය", "චුට්ටි මුහුණු සැරසිලි යෙදීම", "කුමිල් සාය පැළඳීම", "වන්නම් පද ගයමින් ගැටබෙර නාදයට අඩව් හා කස්තිරම් ඇල්ලීම උඩරට අනන්‍යතාවයි."),
        q("පහතරට නර්තනය හා ඉන්දියාවේ කථකලි සම්ප්‍රදාය අතර දැකිය හැකි පොදු සමානකම කුමක්ද?", "විශාල හිස් පැළඳුම්, මුහුණු සැරසිලි හා රාත්‍රී රංගනය", "පිත්තල තැටියේ ගැටිය මත සමතුලිතව නැටීම", "ඇඟිලි තුඩුවලින් පොයින්ට් සපත්තු පැළඳ නැටීම", "හිස මත දිය කළ කිහිපයක් තබාගෙන ගමන් කිරීම", "මෙම සම්ප්‍රදායන් දෙකම රාත්‍රී කාලයේ පන්දම් එළියෙන් දේව හා යක්ෂ පුවත් රඟ දක්වයි."),
        q("සබරගමු නර්තනයේ පපුව සහ උරහිස් කොටසේ ඇති නම්‍යශීලී චලන හා දීර්ඝ ලය ඉන්දීය කුමන නර්තනයට සමීප සෞන්දර්යයක් පෙන්වයිද?", "මණිපුරි හා මෝහිනීඅට්ටම් නර්තනවල මෘදු ලාලිත්‍යයට", "කථකලි හි රෞද්‍ර වේෂයට", "කථක් හි චක්කර් කැරකීමට", "සිංහ නැටුමට", "සබරගමු නැටුමේ පහත් වී නැගෙන දිගු තාල ලයෙහි ලස්ය ස්වභාවය මණිපුරි මෘදු බවට සමානය."),
        q("විදේශීය නර්තන සම්ප්‍රදායක් වන ස්පාඤ්ඤයේ 'ෆ්ලැමෙන්කෝ' (Flamenco) නර්තනයේ විශේෂ ලක්ෂණය කුමක්ද?", "ගිටාර් වාදනය, අත්පුඩි හා පාද සපත්තු තාලය", "කැටයම් කළ දැව වෙස්මුහුණු පැළඳ රඟපෑම", "උඩරට ගැටබෙර හා තාලම්පට වාදනය කිරීම", "පොයින්ට් සපත්තුවෙන් ඇඟිලි තුඩින් සිට ගැනීම", "ෆ්ලැමෙන්කෝ නර්තනයේ සපත්තු විළුඹ පොළොවට ගැසීමෙන් ප්‍රබල රිද්මයක් නිපදවයි."),
        q("හවායි දූපත්වල සම්ප්‍රදායික 'හුලා' (Hula) නර්තනයේ මූලික අරමුණ කුමක්ද?", "ගීතයේ අර්ථය සහ සොබාදහම අත් චලන මගින් කතාවක් සේ නිරූපණය කිරීම", "අසිපත් සටන් පුහුණු වීම", "වෙස්මුහුණු ප්‍රදර්ශනය කිරීම", "වේගවත් කැරකීම් කිරීම", "හුලා නර්තනයේ අත් හා උකුළු චලන මගින් මල්, සුළඟ, මුහුද හා ආදරය ප්‍රකාශ කෙරේ."),
        q("නූතන බටහිර බැලේ නර්තනයේ ස්ත්‍රී නර්තන ශිල්පිනියන් ඇඟිලි තුඩුවලින් සිට ගැනීම සඳහා පළඳින විශේෂ පාවහන් වර්ගය කුමක්ද?", "පොයින්ට් සපත්තු (Pointe shoes)", "සිළම්බු", "ගුංගුරු", "සඳුන් පාවහන්", "පොයින්ට් සපත්තුවල ඉදිරිපස දැඩි ලෙස සකසා ඇති බැවින් ඇඟිලි තුඩුවලින් සමතුලිතව සිටිය හැක."),
        q("පුරාණ ඉන්දියානු හා ශ්‍රී ලාංකේය නර්තන සම්ප්‍රදායන්හිදී වේදිකාවට ප්‍රවේශ වීමට පෙර සිදු කරන පොදු සිරිත කුමක්ද?", "භූමි වන්දනාව සහ ගුරු හා දේව ආචාරය", "ප්‍රේක්ෂකයන්ගෙන් මුදල් එකතු කිරීම", "වේදිකා විදුලි පහන් නිවීම", "බෙර වාදකයාට ඉදිරියෙන් වාඩි වීම", "භූමිය මවක් ලෙස සලකා දෑතින් පොළොව ස්පර්ශ කර නමස්කාර කිරීම පෙරදිග නැටුමේ උසස් සිරිතකි."),
        q("ශ්‍රී ලංකාවේ නර්තන ක්ෂේත්‍රයට ඉන්දීය භරත නාට්‍යම් හා කථකලි ආභාසය ගෙන ආ පුරෝගාමී ශිල්පීන් අතර කැපී පෙනෙන විද්වතා කවුද?", "චිත්‍රසේන සහ වසන්ත කුමාර", "මහගම සේකර", "ඩබ්.ඩී. අමරදේව", "මුනිදාස කුමාරතුංග", "චිත්‍රසේන හා වසන්ත කුමාර ශාන්තිනිකේතනයේ හා කේරළයේදී පුහුණුව ලබා ලංකාවේ මුද්‍රා නාට්‍ය දියුණු කළහ."),
        q("දකුණු ඉන්දියාවේ කේරළ කලාමණ්ඩලම් හි කථකලි හැදෑරූ ලාංකේය නර්තන ආචාර්යවරයෙකු වන්නේ කවුද?", "වසන්ත කුමාර", "පණීභාරත", "ජේ.ඊ. සේදරමන්", "ටික්කිරි බණ්ඩා", "වසන්ත කුමාර කේරළයේ කථකලි හදාරා එහි රංග තාක්ෂණය මෙරට මුද්‍රා නාට්‍යවලට එක් කළේය."),
        q("රවීන්ද්‍රනාත් තාගෝර්තුමාගේ ශාන්තිනිකේතනයෙන් අධ්‍යාපනය ලබා භාරතීය හා දේශීය නර්තන සම්මිශ්‍රණය කළ මෙරට ශිල්පියා කවුද?", "පණීභාරත සහ චිත්‍රසේන", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "හෙන්රි ජයසේන", "ශාන්තිනිකේතන සම්ප්‍රදාය හරහා ලංකාවේ දේශීය නර්තනයට නව වේදිකා රංග ආකෘතියක් හිමි විය."),
        q("නර්තන විද්‍යාවේදී 'පද්ධති' හෙවත් දෙපා සමව තබා සිට ගැනීම අභිනය දර්පණයෙහි හඳුන්වන්නේ කුමන ස්ථානකය ලෙසද?", "සමපාද ස්ථානකය", "මණ්ඩල ස්ථානකය", "ප්‍රත්‍යාලීඩ ස්ථානකය", "ගරුඩ ස්ථානකය", "සමපාද ස්ථානකයේදී දෙපා එකට එක්කර සෘජුව සිටගෙන දෙවියන්ට පූජා හෝ ආශිර්වාද දක්වයි."),
        q("අභිනය දර්පණයට අනුව දණහිස් දෙපසට නවා ඉදිරියෙන් හා පසුපසින් පාද තබා යුදමය හෝ දුනු විදින ඉරියව්ව දැක්වීම කුමන ස්ථානකයද?", "ආලීඩ සහ ප්‍රත්‍යාලීඩ ස්ථානකය", "සමපාද ස්ථානකය", "ඒකපාද ස්ථානකය", "නාගබන්ධ ස්ථානකය", "දුනු විදීමේදී ඉදිරි පාදය නවා පසු පාදය දිගු කරන ආලීඩ ඉරියව්ව උඩරට හා භාරත නැටුම් දෙකේම ඇත."),
        q("තනි කකුලෙන් සිටගෙන අනෙක් කකුල දණහිස අසල තබන 'ඒකපාද' ස්ථානකය නිරූපණය සඳහා බහුලව යොදන්නේ කුමක් දැක්වීමටද?", "තපස් රැකීම හා නිශ්චල බව", "දුනු විදීම හා යුද සටන", "වේගවත් කැරකීම හා පිනුම්", "දෙපා බිම තැබූ මණ්ඩි ගමන", "සෘෂිවරුන්ගේ ඒකාග්‍රතාව හා භාවනා ඉරියව් දැක්වීමට ඒකපාද ස්ථානකය භාවිත කෙරේ."),
        q("අභිනය දර්පණයෙහි සඳහන් වන 'චාරී' යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "තනි පාදයක හා උකුළේ සමගාමී ගමන් චලන", "හිස දෙපසට සෙලවීම", "ඇහිබැම ඉහළ දැමීම", "අත්පුඩි ගැසීම", "භූමිය මත හා අහසෙහි පාද හසුරුවන ආකාරය භූමි චාරී හා ආකාශ චාරී ලෙස වර්ග කෙරේ."),
        q("අහසට පැන සිදු කරන නර්තන පියවර හා පිනුම් වර්ගීකරණය වන්නේ කුමන චාරී ගණයටද?", "ආකාශ චාරී", "භූමි චාරී", "ශිරෝ භේද", "දෘෂ්ටි භේද", "පොළොවෙන් ඉහළට එසවී කරන චලන ආකාශ චාරී වන අතර උඩරට මණ්ඩි පිනුම් ඊට නිදසුන් වේ."),
        q("අභිනය දර්පණයට අනුව 'මණ්ඩල' යනු කුමක්ද?", "සම්මිශ්‍රණ පාද ඉරියව් සහ චාරී සමූහයක එකතුව", "හිස වටේ පළඳින මාලය", "බෙරයේ වම් ඇස", "සායක කොටස", "භ්‍රමරි, මණ්ඩල හා උත්ප්ලවන යනු සම්භාව්‍ය නර්තනයේ උසස් ගමන් හා පිනුම් පද්ධති වේ."),
        q("හිස සහ බෙල්ල ඍජුව තබාගෙන දෙපසට කෙටියෙන් චලනය කිරීම භාරතීය නර්තනයේදී හඳුන්වන්නේ කෙසේද?", "අට්ටමි හෙවත් සුන්දරි ග්‍රීවා භේදය", "ත්‍රිභංග", "චක්කර්", "අරමණ්ඩි", "ගෙල තිරස්ව දෙපසට චලනය කරන අට්ටමි චලනය භරත නාට්‍යම් හා ඔඩිසි නැටුම්වලට අනන්‍ය ලක්ෂණයකි."),
        q("ශ්‍රී ලංකාවේ දේශීය නර්තන ශිල්පියෙකු හස්ත මුද්‍රා භාවිතයේදී විශේෂයෙන් සැලකිලිමත් විය යුතු කරුණ කුමක්ද?", "මුද්‍රාවේ නිවැරදි ජ්‍යාමිතික හැඩය හා ශරීරය සමඟ ඇති සමානුපාතික බව", "ඇඟිලි සියල්ල නිතරම කඩා දැමීම", "දෑත් හිසට පිටුපසින් සඟවා ගැනීම", "ඇස් පියාගෙන නැටීම", "අපහැදිලි හා ලිහිල් ඇඟිලි හැඩ නිසා මුද්‍රාවේ අර්ථය විකෘති වන බැවින් නිවැරදි හැඩය රැකීම අත්‍යවශ්‍යය."),
        q("නර්තන විද්‍යාවේදී 'භ්‍රමරි' යන යෙදුමෙන් හඳුන්වනු ලබන්නේ කුමක්ද?", "නර්තනයේදී සිදු කරන විවිධ වට කැරකීම් භේද", "මුහුණේ වේෂ නිරූපණය", "බෙර වාදන අවසානය", "වේදිකා පසුබිම", "චක්‍ර භ්‍රමරි, උත්ප්ලවන භ්‍රමරි ආදී කැරකීම් අභිනය දර්පණයෙහි විස්තර කෙරේ."),
        q("අභිනය දර්පණයට අනුව 'උත්ප්ලවන' යන්නෙන් අදහස් කෙරෙන නර්තන අංගය කුමක්ද?", "උඩ පැනීම් හෙවත් පිනුම් වර්ග", "හිඳගෙන නැටීම", "අත්පුඩි ගැසීම", "නිහඬව සිට ගැනීම", "හංස ප්ලවන, ගරුඩ ප්ලවන වැනි උඩ පැනීම් උත්ප්ලවන ලෙස හැඳින්වෙන අතර අපේ පිනුම්වලට සමානය."),
        q("උඩරට නර්තනයේ එන 'ඉරට්ටිය' හා 'කස්තිරම' ඉන්දියානු භරත නාට්‍යම් හි කුමන අංගයට බෙහෙවින් සමාන කාර්යයක් ඉටු කරයිද?", "තීර්මානම් හෙවත් කෝර්වෙයි සඳහා", "පදම් අභිනය සඳහා", "වන්දනා ගීත සඳහා", "මිනුක්කු වේෂය සඳහා", "තාල අවසානයක තෙවරක් ගසා සම මත නවත්වන තීර්මානම් කස්තිරම්වලට සමාන වේ."),
        q("මලයාසියාවේ හා ඉන්දුනීසියාවේ සම්ප්‍රදායික නර්තන සඳහා පසුබිම් සංගීතය සපයන ලෝහමය වාද්‍ය භාණ්ඩ වෘන්දය කුමක්ද?", "ගැමෙලාන් වාද්‍ය වෘන්දය", "පංචතූර්ය වෘන්දය", "කර්ණාටක වෘන්දය", "ජෑස් වාද්‍ය වෘන්දය", "සයිලෝෆෝන් හා ගොං වර්ගවලින් සැදුම්ලත් ගැමෙලාන් වාදනය ජාවා හා බාලි නැටුම්වලට අත්‍යවශ්‍යය."),
        q("ඉන්දීය ශාස්ත්‍රීය නර්තනයේ අත්පොත් තැබීමේදී ප්‍රථමයෙන්ම පුහුණු වන 'තට්ටඩවු' හි අර්ථය කුමක්ද?", "පාදයෙන් පොළොවට තාලයට ගැසීමේ මූලික පුහුණුව", "අත් දෙක ඉහළට එසවීම", "හිස කරකැවීම", "වේදිකාව සැරසීම", "අරමණ්ඩි ඉරියව්වෙන් සිට පාද පතුලෙන් බිමට ගසමින් රිද්මය හුරු කිරීම තට්ටඩවු නම් වේ."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' සහ 'දඬියම් සරඹ' පුහුණු වීම ඉන්දීය නර්තනයේ කුමන පුහුණුවට සමාන වැදගත්කමක් දරයිද?", "අඩවු පුහුණුවට", "ගීත රචනයට", "වේෂ නිරූපණයට", "ආලෝකකරණයට", "මූලික අංගචලන, සමබරතාව සහ රිද්මය ගොඩනඟා ගැනීමට සරඹ හා අඩවු පදනම සපයයි."),
        q("පහතරට නර්තනයේ දැකිය හැකි වේගවත් බමන කැරකීම් සහ අඩි ගැසීම් ඉස්මතු කරන්නේ කුමන ගුණයද?", "තාණ්ඩව ගුණය හෙවත් ජවසම්පන්න බව", "නිහඬ භාවනා ගුණය", "සෝකාකූල හැඬීම", "නිදිමත ස්වභාවය", "පහතරට යක් බෙර නාදයට තබන වේගවත් පියවර හා කැරකීම් ප්‍රබල තාණ්ඩව ශක්තියක් පෙන්වයි."),
        q("ශ්‍රී ලංකාවේ දේශීය හා භාරතීය නර්තන අධ්‍යාපනයේදී හස්ත මුද්‍රා හැදෑරීමේ ප්‍රධාන ප්‍රායෝගික වාසිය කුමක්ද?", "අංග ප්‍රත්‍යංග සුමට වීම හා සූක්ෂ්ම අදහස් නිරූපණ හැකියාව වැඩි වීම", "රංග වස්ත්‍ර හා ඇඳුම් මැසීමේ වේගය වැඩි වී කාලය ඉතිරි වීම", "බෙර කඳන්වල ගව සම් සවි කර වරපටි ඇදීම පහසු වීම", "නර්තන රඟ මඩලේ භෞතික දිග හා පළල විශාල කර පෙන්වීම", "නිවැරදි මුද්‍රා පුහුණුව මගින් නර්තන ශිල්පියාගේ සන්නිවේදන ශක්තිය ඉහළ යයි."),
        q("සංයුත හස්ත මුද්‍රාවක් වන 'කටකාවර්ධන' මුද්‍රාව නිර්මාණය කිරීමට යොදාගන්නා අසංයුත හස්ත යුගලය කුමක්ද?", "කටකාමුඛ හස්ත දෙක", "මුෂ්ටි හස්ත දෙක", "සූචි හස්ත දෙක", "ශිඛර හස්ත දෙක", "කටකාමුඛ හස්ත දෙක මැණික් කටුව අසලින් හරස් කළ විට කටකාවර්ධන මුද්‍රාව ලැබේ."),
        q("සංයුත හස්ත මුද්‍රාවක් වන 'පුෂ්පපුට' මුද්‍රාව නිර්මාණය කිරීමේදී යොදාගන්නා අසංයුත හස්තය කුමක්ද?", "සර්පශීර්ෂ හස්ත දෙක", "මයුර හස්ත දෙක", "කර්තරිමුඛ හස්ත දෙක", "සූචි හස්ත දෙක", "සර්පශීර්ෂ හස්ත දෙක පාර්ශ්වයෙන් යා කර මල් දෝතක් මෙන් තැබීමෙන් පුෂ්පපුට සෑදේ."),
        q("සිව්වන හස්ත මුද්‍රාවක් ලෙස ගස්වල ලපටි දළු හා කොළ අතු දැක්වීමට යොදාගන්නා අමතර අසංයුත හස්තය කුමක්ද?", "පල්ලව හස්තය", "වරාහ හස්තය", "ශකට හස්තය", "ඩෝලා හස්තය", "අභිනය දර්පණයට අමතරව රසරත්නාකරය වැනි ග්‍රන්ථවල පල්ලව, නිකුංච ආදී හස්තද විස්තර කෙරේ."),
        q("අසංයුත හස්ත අතරින් 'අරාල' හා 'ශුකතුණ්ඩ' යන මුද්‍රා දෙකෙහි ඇති මූලික වෙනස කුමක්ද?", "අරාලයේ දබරැඟිල්ල පමණක් නැවෙන අතර ශුකතුණ්ඩයේදී වෙදැඟිල්ලද නැවේ", "අරාලය දෑතින්ම දක්වන අතර ශුකතුණ්ඩය තනි අතින් දක්වයි", "ශුකතුණ්ඩයේ සියලු ඇඟිලි මිට මොළවයි", "අරාලයේ සුළැඟිල්ල පමණක් දිගු කරයි", "පතක හස්තයේ සිට දබරැඟිල්ල නැවීමෙන් අරාලයද වෙදැඟිල්ල එක් කිරීමෙන් ශුකතුණ්ඩයද සෑදේ."),
        q("අසංයුත හස්ත අතරින් 'පතක', 'ත්‍රිපතක' සහ 'අර්ධපතක' යන මුද්‍රා තුනෙහි පොදු ලක්ෂණය කුමක්ද?", "මහපටැඟිල්ල නවා අත්ල දෙසට තබා ගැනීම", "සුළැඟිල්ල පමණක් ඉහළට එසවීම", "මැදැඟිල්ල නවා තැබීම", "ඇඟිලි පහම මිට මෙළවීම", "ත්‍රිපතක හා අර්ධපතක යන මුද්‍රා දෙකම නිර්මාණය වන්නේ පතක හස්තය මූලික කරගෙනය."),
        q("හස්ත මුද්‍රා භාවිතයේදී වම් අත පපුව මට්ටමින් ඉදිරියට තබා දකුණු අත වටේට ගෙන යමින් රඟදක්වන ප්‍රධාන රීතිය කුමක්ද?", "සමතුලිත අභිනය අවකාශය රැකීම", "වම් අත අක්‍රිය කර තැබීම", "පසුපස හැරී නැටීම", "අත් දෙකම පහළ හෙළීම", "මුද්‍රා ප්‍රදර්ශනයේදී වම් හා දකුණු දෑත් පපුව හා උරහිස් සීමාව තුළ ප්‍රේක්ෂකයාට පෙනෙන සේ පිහිටිය යුතුය."),
        q("භාරතීය ශාස්ත්‍රීය නර්තන අට අතරට අයත් නොවන විදේශීය නර්තන සම්ප්‍රදාය කුමක්ද?", "නෝ නර්තනය", "මණිපුරි", "ඔඩිසි", "සත්ත්‍රියා", "භරත නාට්‍යම්, කථක්, කථකලි, මණිපුරි, කුචිපුඩි, ඔඩිසි, මෝහිනීඅට්ටම් හා සත්ත්‍රියා ඉන්දීය සම්භාව්‍ය නර්තන වේ."),
        q("දේශීය නර්තන ශිල්පීන්ට විදේශීය නර්තන සම්ප්‍රදායන් හැදෑරීමෙන් ලැබෙන ප්‍රධානතම ප්‍රතිලාභය කුමක්ද?", "සංස්කෘතික සංසන්දනය හා නව නිර්මාණකරණ දැක්ම පුළුල් වීම", "දේශීය නර්තනය අමතක වීම", "දේශීය බෙර භාවිතය නතර කිරීම", "සම්ප්‍රදායික ඇඳුම් ඉවත් කිරීම", "විවිධ සංස්කෘතීන්හි රිද්ම, මුද්‍රා හා වේදිකාකරණය හඳුනාගැනීමෙන් නිර්මාණ ශක්තිය වැඩි වේ."),
        q("ශ්‍රී ලංකාවේ පාසල් O/L නර්තන විෂය නිර්දේශයට අනුව හස්ත මුද්‍රා හඳුන්වා දී ඇත්තේ කුමන ප්‍රධාන වර්ග දෙක යටතේද?", "අසංයුත හස්ත 28 සහ සංයුත හස්ත 24", "නෘත්ත හස්ත 10 සහ සරඹ හස්ත 12", "පතක හස්ත 18 සහ මුෂ්ටි හස්ත 16", "වන්නම් හස්ත 18 සහ සන්නි හස්ත 18", "අභිනය දර්පණයෙහි එන අසංයුත 28 සහ සංයුත 24 පාසල් විෂය මාලාවේ උගන්වනු ලැබේ."),
        q("උඩරට නැට්ටුවෙකු සභාවට වන්දනා කිරීමේදී පළමුව බිමට නැමී කරන 'සෙලෙයියම' හෙවත් ආචාරයේදී පාවිච්චි කරන අතේ ඉරියව්ව කුමක්ද?", "දෑත් එක්කළ අංජලී මුද්‍රාවෙන් හා භූමි ස්පර්ශයෙන්", "ශිඛර හස්තය පමණක් එසවීමෙන්", "සූචි හස්තයෙන් ඇඟිල්ල දිගු කිරීමෙන්", "මුෂ්ටි හස්තයෙන් පොළොවට ගැසීමෙන්", "ප්‍රේක්ෂක සභාවට, බෙරයට හා භූමියට ගෞරව දැක්වීම අංජලී මුද්‍රාවෙන් සිදු කෙරේ."),
        q("කථකලි නැටුමේදී ඇඳුම් කට්ටලය යටින් අඳින පළල් සුදු පැහැති සාය සිහිගන්වන්නේ කුමන හැඩයක්ද?", "නෙළුම් මලක් බඳු පුළුල් රැළි සහිත පෙනුමකි", "පාද වටා තදින් ඇලුණු සෘජු දිගු කලිසමකි", "දණහිසින් ඉහළට ඇඳි කෙටි සරල ධෝතියකි", "උඩුකයට පමණක් බඳින ලද තද බඳ පටියකි", "අඩුරු වස්ත්‍ර හෙවත් කථකලි සාය රැලි කිහිපයකින් යුක්තව අධිමානුෂික පෞරුෂයක් ගෙන දෙයි."),
        q("කුචිපුඩි නර්තනය ආරම්භ වූයේ ඉන්දියාවේ කුමන ශ්‍රේෂ්ඨ ගුරුවරයාගේ මඟපෙන්වීම යටතේද?", "සිද්ධේන්ද්‍ර යෝගී", "භරත මුනි", "ශංකරදේව", "නන්දිකේශ්වර", "සිද්ධේන්ද්‍ර යෝගීතුමා බ්‍රාහ්මණ පිරිමි දරුවන් පුහුණු කර භාමා කලාපම් නාට්‍යය බිහි කළේය."),
        q("භරත නාට්‍යම් නැටුමේ 'පුෂ්පාංජලී' යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "මල් දෝතින් දෙවියන්, ගුරුවරුන් හා සභාව පුදන ආරම්භක අංගය", "ප්‍රසංගය අවසානයේ තබන තිල්ලානාව", "බෙර වාදකයාගේ තනි වාදනය", "ඇඳුම් මාරු කරන විරාමය", "පුෂ්පාංජලී හිදී නැට්ටුවා පුෂ්පපුට හස්තයෙන් මල් පුදා සභාවට ආචාර කරයි."),
        q("භාරතීය හා ශ්‍රී ලාංකේය නර්තනයන්හිදී 'සතර වරම් දෙවියන්' හෝ 'අෂ්ට දික්පාලකයන්' වන්දනා කිරීම සිදුවන්නේ කුමන අවස්ථාවේද?", "ප්‍රසංගයේ හෝ ශාන්තිකර්මයේ ආරම්භක වන්දනාවේදී", "රංගනය අවසන් වී නිවසට යන විට", "වේෂ නිරූපණය මකා දමන විට", "භාණ්ඩ ඇසුරුම් කරන විට", "ආරක්ෂාව හා ආශිර්වාදය පතා රංග පීඨයට පූජා කිරීම ආරම්භක සම්ප්‍රදායයි."),
        q("දේශීය හා ඉන්දීය සම්භාව්‍ය නර්තනයන්හිදී පිරිමි හා කාන්තා නර්තන අනන්‍යතාවන් පැහැදිලි කරන යෙදුම් යුගලය කුමක්ද?", "තාණ්ඩව සහ ලස්ය", "නෘත්ත සහ නාට්‍ය", "රාග සහ තාල", "සම සහ ඛාලි", "තාණ්ඩව ප්‍රබල පුරුෂ ගුණයද ලස්ය මෘදු ස්ත්‍රී ගුණයද නියෝජනය කරයි."),
        q("ප්‍රසංග වේදිකාවක නර්තන ශිල්පියෙකු හස්ත මුද්‍රා පෙන්වන විට ඇඟිලිවල රතු පැහැති ආලේපනයක් (අල්තා) ගල්වන්නේ ඇයි?", "මුද්‍රා හැඩය හා පාද චලන පැහැදිලිව දිස්වීමට", "වේදිකාව මත පාද ලිස්සා යාම වළක්වා ගැනීමට", "රංගනය අතරතුර දෑත් සීතලෙන් ආරක්ෂා කිරීමට", "වෙස්මුහුණු වර්ණ ගැන්වීමේ තීන්ත සෑදීමට", "රතු අල්තා වර්ණය නිසා දුර සිට බලන ප්‍රේක්ෂකයාට ඇඟිලි හැඩතල ඉතා පැහැදිලිව පෙනේ."),
        q("අසංයුත හස්ත 28 න් 'මයුර' හස්තය සහ 'අර්ධචන්ද්‍ර' හස්තය එකිනෙක වෙනස් වන්නේ කෙසේද?", "මයුරයේ වෙදැඟිල්ල මහපටැඟිල්ලට තබන අතර අර්ධචන්ද්‍රයේදී මහපටැඟිල්ල පිටතට විහිදුවයි", "මයුර හා අර්ධචන්ද්‍ර දෙකෙහිම සුළැඟිල්ල පමණක් පහළට නවා ඉතිරි ඇඟිලි දිග හරියි", "මයුර තනි අතින් දැක්වුවද අර්ධචන්ද්‍රයේදී සෑම විටම දෑත් දෙකම එක් කොට යොදයි", "මයුර හස්තයේ සියලුම ඇඟිලි පහ අත්ල මැදට තදින් මිට මොළවා තබා ගනියි", "මයුර හස්තයේ මොනර හොට සේ වෙදැඟිල්ල හා මහපටැඟිල්ල එක් කරන අතර අර්ධචන්ද්‍රයේ පතකයෙන් මහපටැඟිල්ල විහිදුවයි."),
        q("හස්ත මුද්‍රාවක අර්ථය වෙනස් වීම සඳහා බලපාන ප්‍රධාන සාධකයක් වන්නේ කුමක්ද?", "අත තබාගන්නා ස්ථානය, චලනය වන දිශාව සහ මුහුණේ භාවය", "රංග වස්ත්‍රයේ මිල", "වේදිකාවේ පළල", "ප්‍රේක්ෂක සංඛ්‍යාව", "එකම පතක හස්තය හිස මත, පපුවේ හෝ පහළ තැබීමෙන් විවිධ අර්ථ උපදවයි."),
        q("චක්කර් කැරකීම් කිරීමේදී කථක් ශිල්පියෙකු හිස කරකැවීමෙන් කරකැවිල්ල (වමනය හෝ කරකැවෙන ගතිය) වළක්වා ගන්නේ කෙසේද?", "ඉදිරිපස එක් ලක්ෂ්‍යයක් වෙත ඇස රඳවා අවසන් මොහොතේ හිස ඉක්මනින් හැරවීමෙන්", "කැරකීම ආරම්භයේ සිට අවසානය දක්වාම ඇස් තදින් පියාගෙන වේගයෙන් කැරකීමෙන්", "දෙපයේ මහපටැඟිලි දෙස නොකඩවා බිම බලාගෙන හිස පහත් කර කැරකීමෙන්", "වටය කැරකෙන අතරතුර දෑතින් කන් දෙක හා නාසය තදින් වසා ගෙන සිටීමෙන්", "එක් ස්ථාවර ලක්ෂ්‍යයක් දෙස බලා සිටීම (Spotting) කථක් හා බැලේ කැරකීම්වල විද්‍යාත්මක ක්‍රමයයි."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව සම්භාව්‍ය නර්තනයක් අධ්‍යයනය කරන ශිෂ්‍යයෙකු සතු විය යුතු මූලික ශාරීරික ගුණාංගය කුමක්ද?", "නම්‍යශීලී බව, සමබරතාව හා රිද්ම සංවේදීතාව", "වේගවත් කතා විලාසය හා උස් හඬ පමණක්", "අධික ශරීර බර හා නිශ්චල ඉරියව් පමණක්", "වෙස්මුහුණු කැපීමේ මූර්ති ශිල්පීය හැකියාව", "නිරෝගී හා නම්‍යශීලී දේහයත් රිද්ම හා භාව අවබෝධයත් නර්තන ශිල්පියාගේ පදනමයි."),
        q("ශ්‍රී ලංකාවේ හා ඉන්දියාවේ සම්භාව්‍ය නර්තන වේදිකාවේදී පහන් දැල්වීමෙන් සහ මංගල බෙර වැයීමෙන් බලාපොරොත්තු වන්නේ කුමක්ද?", "ශුභාරම්භය, පවිත්‍ර පරිසරය හා ආශිර්වාදය පැතීම", "වේදිකාවේ ප්‍රමාණය පුළුල් කර රත් කර ගැනීම", "රංගනය ආරම්භයට පෙර ප්‍රේක්ෂකයන් බිය ගැන්වීම", "ප්‍රධාන නැටුම පමා වන තුරු කාලය ගත කිරීම", "පහන් දැල්වීම අඳුර නසා කලාත්මක ආලෝකය උදා කරන මංගල චාරිත්‍රයකි."),
        q("තාලමකට අනුව දෑත් පහත හෙළා සමබරව සිටීම දක්වන 'ඩෝලා' හස්තය වෙනුවට ඇතැම් විට ගසක අතු සෙලවීම දැක්වීමට යොදන හස්තය කුමක්ද?", "ලතා හස්තය", "මුෂ්ටි හස්තය", "කර්කට හස්තය", "ශකට හස්තය", "වැල් හා ගස් අතු ලෙළදීම නිරූපණය කිරීම සඳහා ලාලිත්‍යමය ලතා හස්තය යොදාගනී."),
        q("බලි නැටුම් හා උඩරට වන්නම්වලදී අත දිගු කර දිශාවන් පෙන්වීම හෝ තනි වස්තුවක් දැක්වීම සඳහා ගැළපෙන මුද්‍රාව කුමක්ද?", "සූචි හස්තය", "මත්ස්‍ය හස්තය", "කපෝත හස්තය", "ශිවලිංග හස්තය", "දබරැඟිල්ල දිගු කරන සූචි හස්තය දිශාව, තනි අංකය හා පුද්ගලයෙකු දැක්වීමට යොදයි."),
        q("සම්ප්‍රදායික කථකලි නර්තනයේදී වීරයෙකු කෝපය හෝ බලය පෙන්වීමට කාල වේගය වැඩි කර නටන රංගන කොටස කුමක්ද?", "කලශම්", "මිනුක්කු", "ඩෝලා", "අලාරිප්පු", "කලශම් යනු ගීත පද පෙළි අතරතුර යෙදෙන වේගවත් ශුද්ධ නෘත්ත කොටසයි."),
        q("ඔඩිසි නර්තනයේදී ගීත ගෝවින්ද කාව්‍යයේ එන 'අෂ්ටපදි' ගයමින් අභිනය කරන අංගය මඟින් නිරූපණය වන්නේ කුමක්ද?", "රාධා සහ ක්‍රිෂ්ණා අතර ඇති භක්ති හා ශෘංගාර රසය", "කැලණි ඇසළ පෙරහැරේ ධාතු වැඩමවීමේ චාරිත්‍රය", "පහතරට දහඅට සන්නි යාගයේ රෝග සමන පෙළපාලිය", "සිංහබාහු නාටකයේ සිංහපුර වනගත නාට්‍යමය අවස්ථාව", "ජයදේව කවියාගේ ගීත ගෝවින්ද කාව්‍යය ඔඩිසි අභිනය අංග සඳහා ප්‍රධාන මූලාශ්‍රය වේ."),
        q("ලංකාවේ නූතන නර්තන වේදිකාවේ මුද්‍රා නාට්‍ය කලාව ආරම්භයේදී සංස්කෘතික පුනරුදයට දායක වූ ප්‍රධාන නිර්මාණයක් කුමක්ද?", "කරදිය සහ නල දමයන්ති", "මනමේ සහ සිංහබාහු පමණක්", "කෝලම් හා සොකරි", "දහඅට සන්නිය", "චිත්‍රසේනගේ කරදිය හා නල දමයන්ති මෙරට නූතන මුද්‍රා නාට්‍යයේ මහා සන්ධිස්ථාන වේ."),
        q("මුද්‍රා නාට්‍යයකදී දෙබස් නොමැතිව කතාවක් සම්පූර්ණයෙන්ම ඉදිරිපත් කරන්නේ කුමන මාධ්‍යයන්ගෙන්ද?", "නර්තන චලන, හස්ත මුද්‍රා, මුහුණේ භාව සහ සංගීතයෙන්", "ලිඛිත පොත් බෙදා හැරීමෙන්", "ප්‍රේක්ෂකයන්ගේ කතාබහෙන්", "කථිකයන්ගේ දේශනවලින්", "මුද්‍රා නාට්‍යය යනු ශබ්ද දෙබස් රහිතව ශරීර භාෂාවෙන් හා සංගීතයෙන් කතාව මැවෙන රංග කලාවකි.")
    )
}
